css:
  :root {
    --chrome: #141712;
    --chrome-raised: #191d17;
    --chrome-ink: #f4f5ee;
    --chrome-muted: #a0a79a;
    --chrome-line: rgba(255, 255, 255, 0.08);
    --paper: #f1f0e9;
    --surface: #fbfaf6;
    --surface-soft: #f6f4ee;
    --ink: #1b1e18;
    --ink-soft: #41463c;
    --muted: #666b60;
    --faint: #6c7165;
    --line: #e2e0d6;
    --line-strong: #d3d0c4;
    --forest: #2c6248;
    --forest-deep: #1f4a36;
    --forest-wash: #e8f0e9;
    --signal: #cdeb80;
    --signal-wash: rgba(205, 235, 128, 0.14);
    --rust: #a05240;
    --rust-wash: #f6eae4;
    --rail: 224px;
    --radius: 14px;
    --shadow: 0 1px 2px rgba(20, 24, 17, 0.03), 0 18px 44px -36px rgba(20, 24, 17, 0.32);
    --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
    --serif: ui-serif, "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Georgia, serif;
  }

  *,
  *::before,
  *::after {
    box-sizing: border-box;
  }

  html {
    min-height: 100%;
    -webkit-text-size-adjust: 100%;
  }

  body {
    min-width: 0;
    min-height: 100%;
    margin: 0;
    overflow-x: hidden;
    background: var(--paper);
    color: var(--ink);
    font-family: var(--sans);
    font-size: 14px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }

  button,
  a {
    font: inherit;
  }

  button {
    color: inherit;
  }

  a {
    color: inherit;
  }

  svg {
    display: block;
  }

  ::selection {
    background: var(--signal);
    color: var(--ink);
  }

  :focus-visible {
    outline: 2px solid var(--forest);
    outline-offset: 2px;
  }

  .topbar :focus-visible,
  .sidebar :focus-visible {
    outline-color: var(--signal);
  }

  .sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .app {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
  }

  .topbar {
    position: relative;
    z-index: 5;
    display: flex;
    align-items: stretch;
    min-height: 64px;
    background: linear-gradient(92deg, #171b15 0%, var(--chrome) 56%, #11130f 100%);
    border-bottom: 1px solid var(--chrome-line);
  }

  .brand {
    display: flex;
    flex: 0 0 var(--rail);
    align-items: center;
    gap: 11px;
    min-width: 0;
    padding: 0 22px;
    color: var(--chrome-ink);
    text-decoration: none;
    border-right: 1px solid var(--chrome-line);
  }

  .brand-mark {
    display: grid;
    flex: none;
    width: 28px;
    height: 28px;
    color: #182012;
    background: var(--signal);
    border-radius: 8px;
    place-items: center;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.34);
  }

  .brand-mark svg {
    width: 17px;
    height: 17px;
  }

  .brand-word {
    font-family: var(--serif);
    font-size: 21px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: -0.015em;
  }

  .brand-tag {
    padding: 4px 6px 3px;
    color: var(--chrome-muted);
    font-family: var(--mono);
    font-size: 8px;
    line-height: 1;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    border: 1px solid var(--chrome-line);
    border-radius: 4px;
  }

  .topbar-actions {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
    margin-left: auto;
    padding: 0 22px;
  }

  .env {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    color: #b8beb1;
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.025em;
    white-space: nowrap;
  }

  .env-dot {
    width: 6px;
    height: 6px;
    background: var(--signal);
    border-radius: 50%;
    box-shadow: 0 0 0 3px var(--signal-wash);
  }

  .topbar-divider {
    width: 1px;
    height: 18px;
    background: var(--chrome-line);
  }

  .date-range {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    height: 34px;
    padding: 0 10px;
    color: #edefe7;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: -0.01em;
    white-space: nowrap;
    cursor: pointer;
    transition: background-color 140ms ease, border-color 140ms ease;
  }

  .date-range:hover {
    background: rgba(255, 255, 255, 0.075);
    border-color: rgba(255, 255, 255, 0.2);
  }

  .date-range:focus-visible {
    outline-color: var(--signal);
    outline-offset: 2px;
  }

  .date-range .calendar {
    width: 14px;
    height: 14px;
    color: #aab1a4;
  }

  .date-range .chevron {
    width: 11px;
    height: 11px;
    margin-left: 1px;
    color: #949b8e;
  }

  .avatar {
    position: relative;
    display: grid;
    flex: none;
    width: 34px;
    height: 34px;
    background: linear-gradient(145deg, #e4c096 0%, #c08d65 62%, #a97550 100%);
    color: #352317;
    border: 1px solid rgba(255, 255, 255, 0.22);
    border-radius: 50%;
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.01em;
    place-items: center;
    user-select: none;
  }

  .avatar::after {
    content: "";
    position: absolute;
    right: -1px;
    bottom: -1px;
    width: 8px;
    height: 8px;
    background: var(--signal);
    border: 2px solid var(--chrome);
    border-radius: 50%;
  }

  .shell {
    display: flex;
    flex: 1;
    min-height: 0;
  }

  .sidebar {
    position: relative;
    flex: 0 0 var(--rail);
    min-height: 100%;
    padding: 26px 14px;
    overflow: hidden;
    background: var(--chrome);
  }

  .sidebar::after {
    content: "";
    position: absolute;
    right: -90px;
    bottom: -120px;
    width: 280px;
    height: 280px;
    background: radial-gradient(circle, rgba(205, 235, 128, 0.075) 0%, rgba(205, 235, 128, 0) 66%);
    pointer-events: none;
  }

  .nav-section {
    position: relative;
    z-index: 1;
  }

  .nav-label {
    margin: 0 10px 12px;
    color: #7d8478;
    font-family: var(--mono);
    font-size: 9px;
    font-weight: 500;
    letter-spacing: 0.135em;
    line-height: 1;
    text-transform: uppercase;
  }

  .nav {
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .nav-item {
    position: relative;
    display: flex;
    align-items: center;
    gap: 11px;
    min-height: 40px;
    padding: 0 11px;
    color: #a6ada0;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 450;
    letter-spacing: -0.005em;
    text-decoration: none;
    transition: color 140ms ease, background-color 140ms ease;
  }

  .nav-item svg {
    flex: none;
    width: 17px;
    height: 17px;
    color: #899184;
    transition: color 140ms ease;
  }

  .nav-item:hover {
    color: var(--chrome-ink);
    background: rgba(255, 255, 255, 0.045);
  }

  .nav-item:hover svg {
    color: #c6ccbf;
  }

  .nav-item.is-active {
    color: var(--chrome-ink);
    background: rgba(255, 255, 255, 0.07);
  }

  .nav-item.is-active svg {
    color: var(--signal);
  }

  .nav-item.is-active::before {
    content: "";
    position: absolute;
    top: 9px;
    bottom: 9px;
    left: -14px;
    width: 2px;
    background: var(--signal);
    border-radius: 0 2px 2px 0;
  }

  .main {
    flex: 1;
    min-width: 0;
    padding: 28px 32px 44px;
    background:
      radial-gradient(1000px 520px at 100% -14%, rgba(44, 98, 72, 0.055), transparent 64%),
      radial-gradient(760px 480px at -8% 110%, rgba(205, 235, 128, 0.05), transparent 72%),
      var(--paper);
  }

  .page-heading {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 20px;
  }

  .eyebrow {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 0 0 7px;
    color: var(--muted);
    font-family: var(--mono);
    font-size: 9.5px;
    font-weight: 500;
    letter-spacing: 0.13em;
    line-height: 1;
    text-transform: uppercase;
  }

  .eyebrow::before {
    content: "";
    width: 15px;
    height: 1px;
    background: var(--line-strong);
  }

  .page-title {
    margin: 0;
    color: var(--ink);
    font-family: var(--serif);
    font-size: 33px;
    font-weight: 500;
    line-height: 1.03;
    letter-spacing: -0.025em;
  }

  .page-period {
    flex: none;
    padding-bottom: 5px;
    color: var(--faint);
    font-family: var(--mono);
    font-size: 10px;
    letter-spacing: 0.005em;
    white-space: nowrap;
  }

  .page-period strong {
    color: var(--ink-soft);
    font-weight: 500;
  }

  .page-period .sep {
    padding: 0 3px;
    color: var(--line-strong);
  }

  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    overflow: hidden;
    background: linear-gradient(180deg, #fcfbf7 0%, #f8f6f0 100%);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
  }

  .kpi {
    min-width: 0;
    padding: 18px 20px 17px;
    transition: background-color 160ms ease;
  }

  .kpi + .kpi {
    border-left: 1px solid var(--line);
  }

  .kpi:hover {
    background: rgba(255, 255, 255, 0.62);
  }

  .kpi-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
  }

  .kpi-label {
    color: var(--muted);
    font-size: 11.5px;
    font-weight: 500;
    line-height: 1.2;
    letter-spacing: 0.002em;
  }

  .kpi-icon {
    flex: none;
    width: 16px;
    height: 16px;
    margin-top: -1px;
    color: #969b8e;
  }

  .kpi-figure {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 7px;
    margin-top: 15px;
  }

  .kpi-value {
    color: var(--ink);
    font-size: 28px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    line-height: 1;
    letter-spacing: -0.045em;
  }

  .delta {
    display: inline-flex;
    align-items: center;
    height: 19px;
    padding: 0 6px;
    border-radius: 5px;
    font-family: var(--mono);
    font-size: 10px;
    font-weight: 500;
    letter-spacing: -0.02em;
    line-height: 1;
    white-space: nowrap;
  }

  .delta.is-positive {
    color: #255a41;
    background: var(--forest-wash);
  }

  .delta.is-negative {
    color: #964737;
    background: var(--rust-wash);
  }

  .analysis-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.55fr) minmax(360px, 0.95fr);
    align-items: stretch;
    gap: 18px;
    margin-top: 18px;
  }

  .card {
    min-width: 0;
    background: var(--surface);
    border: 1px solid var(--line);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
  }

  .chart-card,
  .events-card {
    display: flex;
    flex-direction: column;
  }

  .card-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    padding: 20px 20px 0;
  }

  .card-title {
    margin: 0;
    color: var(--ink);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.25;
    letter-spacing: -0.012em;
  }

  .card-sub {
    margin: 4px 0 0;
    color: var(--muted);
    font-size: 11px;
    line-height: 1.4;
  }

  .chip {
    flex: none;
    padding: 4px 8px;
    color: var(--muted);
    background: var(--surface-soft);
    border: 1px solid var(--line);
    border-radius: 99px;
    font-family: var(--mono);
    font-size: 9px;
    letter-spacing: 0.015em;
    line-height: 1.35;
    white-space: nowrap;
  }

  .chart-plot-area {
    display: flex;
    flex: 1;
    flex-direction: column;
    justify-content: flex-end;
    padding: 17px 20px 14px;
  }

  .chart-body {
    position: relative;
    flex: 1 1 auto;
    min-height: 260px;
    padding-left: 38px;
  }

  .y-axis {
    position: absolute;
    top: 0;
    bottom: 0;
    left: 0;
    width: 31px;
    color: var(--faint);
    font-family: var(--mono);
    font-size: 9px;
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }

  .y-axis span {
    position: absolute;
    right: 0;
    transform: translateY(-50%);
  }

  .y-axis span:nth-child(1) { top: 3.33%; }
  .y-axis span:nth-child(2) { top: 34.44%; }
  .y-axis span:nth-child(3) { top: 65.56%; }
  .y-axis span:nth-child(4) { top: 96.67%; }

  .plot {
    --x: 50%;
    --y: 50%;
    position: relative;
    height: 100%;
    isolation: isolate;
  }

  .chart-svg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
  }

  .grid-line {
    stroke: var(--line);
    stroke-width: 1;
    vector-effect: non-scaling-stroke;
  }

  .grid-baseline {
    stroke: var(--line-strong);
  }

  .chart-area {
    fill: url(#eventArea);
  }

  .chart-line {
    fill: none;
    stroke: var(--forest);
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    vector-effect: non-scaling-stroke;
  }

  .chart-points {
    position: absolute;
    inset: 0;
    z-index: 2;
    pointer-events: none;
  }

  .chart-point {
    position: absolute;
    width: 7px;
    height: 7px;
    background: var(--surface);
    border: 1.5px solid var(--forest);
    border-radius: 50%;
    box-shadow: 0 0 0 1px rgba(251, 250, 246, 0.86);
    transform: translate(-50%, -50%);
  }

  .chart-point:last-child {
    width: 10px;
    height: 10px;
    background: var(--forest);
    border-color: var(--surface);
    box-shadow: 0 0 0 3px rgba(44, 98, 72, 0.13);
  }

  .chart-crosshair {
    position: absolute;
    top: 0;
    bottom: 0;
    left: var(--x);
    z-index: 4;
    width: 1px;
    background: linear-gradient(180deg, transparent 0%, rgba(44, 98, 72, 0.34) 10%, rgba(44, 98, 72, 0.34) 90%, transparent 100%);
    opacity: 0;
    pointer-events: none;
    transition: opacity 120ms ease;
  }

  .chart-dot {
    position: absolute;
    top: var(--y);
    left: var(--x);
    z-index: 5;
    width: 9px;
    height: 9px;
    background: var(--forest);
    border: 2px solid var(--surface);
    border-radius: 50%;
    box-shadow: 0 0 0 3px rgba(44, 98, 72, 0.12);
    opacity: 0;
    pointer-events: none;
    transform: translate(-50%, -50%);
    transition: opacity 120ms ease;
  }

  .chart-tooltip {
    position: absolute;
    top: var(--y);
    left: clamp(52px, var(--x), calc(100% - 52px));
    z-index: 6;
    display: flex;
    flex-direction: column;
    gap: 1px;
    padding: 6px 8px;
    color: var(--chrome-ink);
    background: var(--ink);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 7px;
    box-shadow: 0 10px 24px -14px rgba(0, 0, 0, 0.5);
    font-family: var(--mono);
    line-height: 1.3;
    opacity: 0;
    pointer-events: none;
    transform: translate(-50%, calc(-100% - 12px));
    transition: opacity 120ms ease;
    white-space: nowrap;
  }

  .chart-tooltip.is-below {
    transform: translate(-50%, 14px);
  }

  .plot.is-inspecting .chart-tooltip,
  .plot.is-inspecting .chart-crosshair,
  .plot.is-inspecting .chart-dot {
    opacity: 1;
  }

  .tt-date {
    color: #a9b0a3;
    font-size: 9px;
    letter-spacing: 0.025em;
  }

  .tt-value {
    color: #f7f8f2;
    font-size: 10.5px;
    letter-spacing: -0.01em;
  }

  .chart-hits {
    position: absolute;
    inset: 0;
    z-index: 3;
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
  }

  .chart-hit {
    width: 100%;
    height: 100%;
    padding: 0;
    margin: 0;
    background: transparent;
    border: 0;
    cursor: crosshair;
  }

  .chart-hit:focus-visible {
    outline: 2px solid var(--forest);
    outline-offset: -2px;
    border-radius: 4px;
  }

  .x-axis {
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    margin-top: 9px;
    margin-left: 38px;
    color: var(--faint);
    font-family: var(--mono);
    font-size: 9px;
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }

  .x-axis span {
    text-align: center;
    white-space: nowrap;
  }

  .table-wrap {
    padding: 11px 20px 0;
  }

  .events-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
  }

  .events-table th {
    padding: 0 0 9px;
    color: var(--faint);
    font-family: var(--mono);
    font-size: 8.5px;
    font-weight: 500;
    letter-spacing: 0.095em;
    line-height: 1.2;
    text-align: left;
    text-transform: uppercase;
  }

  .events-table th:nth-child(2) { width: 68px; }
  .events-table th:nth-child(3) { width: 62px; }
  .events-table th:nth-child(4) { width: 50px; }

  .events-table th.num,
  .events-table td.num {
    text-align: right;
  }

  .events-table th.trend,
  .events-table td.trend {
    text-align: right;
  }

  .events-table td {
    height: 46px;
    padding: 0;
    border-top: 1px solid var(--line);
    vertical-align: middle;
  }

  .events-table tbody tr:first-child td {
    border-top-color: var(--line-strong);
  }

  .events-table tbody tr {
    transition: background-color 140ms ease;
  }

  .events-table tbody tr:hover {
    background: rgba(44, 98, 72, 0.035);
  }

  .event-name {
    display: block;
    overflow: hidden;
    color: var(--ink-soft);
    font-family: var(--mono);
    font-size: 11px;
    letter-spacing: -0.02em;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .events-table td.num {
    color: var(--ink-soft);
    font-family: var(--mono);
    font-size: 10.5px;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.015em;
  }

  .trend-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    font-family: var(--sans);
    font-size: 11px;
    line-height: 1;
  }

  .trend-pill.up {
    color: var(--forest);
    background: var(--forest-wash);
  }

  .trend-pill.down {
    color: var(--rust);
    background: var(--rust-wash);
  }

  .table-note {
    margin: auto 20px 0;
    padding: 14px 0 16px;
    color: var(--faint);
    font-size: 10px;
    line-height: 1.4;
    border-top: 1px solid var(--line);
  }

  @media (min-width: 1181px) {
    .analysis-grid {
      min-height: 430px;
    }

    .table-wrap {
      flex: 1;
    }

    .events-table {
      height: 100%;
    }
  }

  @media (max-width: 1180px) {
    .analysis-grid {
      grid-template-columns: minmax(0, 1fr);
    }

    .table-note {
      margin-top: 14px;
    }
  }

  @media (max-width: 900px) {
    .topbar {
      min-height: 56px;
    }

    .brand {
      flex: 0 0 auto;
      padding: 0 18px;
      border-right: 0;
    }

    .topbar-actions {
      padding: 0 18px;
    }

    .shell {
      flex-direction: column;
    }

    .sidebar {
      flex: none;
      width: 100%;
      min-height: 0;
      padding: 0 10px;
      border-bottom: 1px solid var(--chrome-line);
    }

    .sidebar::after {
      display: none;
    }

    .nav-label {
      display: none;
    }

    .nav {
      flex-direction: row;
      gap: 2px;
    }

    .nav-item {
      flex: 1 1 0;
      justify-content: center;
      min-height: 51px;
